const base = 'https://www.coverflex.com';
const pt = ['pt', 'pt/precos', 'pt/wallet', 'pt/cartao-refeicao', 'pt/seguros', 'pt/cheque-infancia', 'pt/flexpay', 'pt/budgets', 'pt/transparencia-salarial', 'pt/proposta-emprego', 'pt/ai', 'pt/descontos', 'pt/beneficios', 'pt/colaborador', 'pt/sobre-nos', 'pt/industrias', 'pt/solucao/gestores-recursos-humanos', 'pt/solucao/diretores-financeiros', 'pt/solucao/ceo-founders', 'pt/solucao/pequenas-empresas', 'pt/solucao/medias-empresas', 'pt/solucao/grandes-empresas'];
const en = ['en-pt', 'en-pt/pricing', 'en-pt/wallet', 'en-pt/meal', 'en-pt/insurance', 'en-pt/childcare', 'en-pt/flexpay', 'en-pt/budgets', 'en-pt/pay-transparency', 'en-pt/job-offer', 'en-pt/ai', 'en-pt/discounts', 'en-pt/benefits', 'en-pt/employee', 'en-pt/about-us', 'en-pt/industries', 'en-pt/solution/small-companies', 'en-pt/solution/medium-companies', 'en-pt/solution/large-companies'];
return [
  ...pt.map(p => ({ json: { url: `${base}/${p}`, lang: 'pt' } })),
  ...en.map(p => ({ json: { url: `${base}/${p}`, lang: 'en' } })),
];

// Turns raw Webflow HTML into light markdown and removes site-wide boilerplate.
// Boilerplate rule: a line that appears on >= 40% of the pages of the same language
// (nav menu, footer, cookie banner, popups) is not page content, so we drop it.
const pages = $('Curated Page List').all();
const responses = $input.all();
const BOILERPLATE_SHARE = 0.4;
const WINDOW = 4;

const entities = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', rsquo: '’', lsquo: '‘', ldquo: '“', rdquo: '”', ndash: '–', mdash: '—', hellip: '…', euro: '€' };
const decode = s => s
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
  .replace(/&([a-z]+);/gi, (m, n) => entities[n.toLowerCase()] ?? m);

function toLines(html) {
  let s = html;
  s = s.replace(/<head\b[\s\S]*?<\/head>/i, ' ');
  s = s.replace(/<(script|style|svg|noscript|form|iframe|template)\b[\s\S]*?<\/\1>/gi, ' ');
  s = s.replace(/<!--[\s\S]*?-->/g, ' ');
  s = s.replace(/<h1\b[^>]*>/gi, '\n# ').replace(/<h2\b[^>]*>/gi, '\n## ').replace(/<h[3-6]\b[^>]*>/gi, '\n### ');
  s = s.replace(/<li\b[^>]*>/gi, '\n- ');
  s = s.replace(/<\/?(p|div|section|br|h[1-6]|li|ul|ol|tr|nav|a|button)\b[^>]*>/gi, '\n');
  s = decode(s.replace(/<[^>]+>/g, ''));
  return s.split('\n')
    .map(l => l.replace(/\s+/g, ' ').trim())
    .filter(l => l && !['#', '##', '###', '-'].includes(l));
}

const parsed = responses.map((r, i) => {
  const html = r.json.html || '';
  const title = decode((html.match(/<title>([^<]*)<\/title>/i) || [])[1] || '').trim();
  return { url: pages[i].json.url, lang: pages[i].json.lang, title, lines: toLines(html) };
});

// Count on how many pages (per language) each line appears.
const freq = { pt: new Map(), en: new Map() };
const total = { pt: 0, en: 0 };
for (const p of parsed) {
  total[p.lang]++;
  for (const l of new Set(p.lines)) freq[p.lang].set(l, (freq[p.lang].get(l) || 0) + 1);
}

// Repeated blocks keep only their first copy (per language): whole sections
// (heading + text) and any run of 4+ lines already seen. Some pages repeat blocks,
// e.g. an older plans block on 5 pages, which otherwise crowds out search results.
const seenSections = { pt: new Set(), en: new Set() };
const seenWindows = { pt: new Set(), en: new Set() };

return parsed.map(p => {
  const out = [];
  for (const l of p.lines) {
    if (freq[p.lang].get(l) >= BOILERPLATE_SHARE * total[p.lang]) continue;
    if (out[out.length - 1] === l) continue;
    const isQuestion = l.endsWith('?') && l.length < 200 && !l.startsWith('#');
    out.push(isQuestion ? `### ${l}` : l);
  }

  const sections = [];
  for (const l of out) {
    if (!sections.length || l.startsWith('#')) sections.push([l]);
    else sections[sections.length - 1].push(l);
  }
  const kept = [];
  for (const s of sections) {
    const key = s.join('\n');
    if (key.length > 40 && seenSections[p.lang].has(key)) continue;
    seenSections[p.lang].add(key);
    kept.push(...s);
  }

  const drop = new Array(kept.length).fill(false);
  for (let i = 0; i + WINDOW <= kept.length; i++) {
    const w = kept.slice(i, i + WINDOW).join('\n');
    if (seenWindows[p.lang].has(w)) for (let j = i; j < i + WINDOW; j++) drop[j] = true;
    seenWindows[p.lang].add(w);
  }

  const text = kept.filter((_, i) => !drop[i]).join('\n');
  return { json: { url: p.url, lang: p.lang, title: p.title, chars: text.length, text } };
});
